/// Phase 396 - the ONE reading of the repository's approval switches.
///
/// A committed artefact in this repository is a PROJECTION of something else (a public-surface
/// baseline, a wire baseline, a generated F# module, a README block, a ratchet file), and each
/// family that holds one is regenerated by setting an environment variable and re-running its
/// tests. There are six such switches (`CORE_APPROVE_API`, `_WIRE`, `_LADDER`, `_README`,
/// `_DOCS`, and `FUARAN_REGEN` at the generated-module sites); before this module each site read
/// its own variable with its own idea of "set" (`<> "" && <> "0"` at some, `= "1"` at others), and
/// none of them could be aimed at one file.
///
/// THE RULE (one truthiness, documented here and in CONTRIBUTING.md and STABILITY.md):
///
///   * absent, empty, `0` or `false` -> NOT requested;
///   * `1` or `true` (any case)      -> requested for EVERY file the switch governs;
///   * anything else                 -> requested for the named file(s) only: the value is a filter,
///                                      a comma-separated list of file stems (a package id for the
///                                      API and wire baselines, the file name without its
///                                      extension for a generated module).
///
/// A filter that names nothing the switch governs is RED BY NAME, never a silent no-op, and every
/// file a switch rewrites is printed, so the "stage by name" step reads the list.
///
/// Phase 503 - what each switch governs is read from the projection registry (`projections.json`),
/// the one list of the artefacts this repository generates; this module reads it and nothing else does.
module Fuaran.Core.Tests.Approval

open System
open System.IO
open System.Text.Json
open Expecto

/// How a switch is set. `Everything` is the bare `1` / `true`; `Only` carries the filter's stems.
type Request =
    | NotRequested
    | Everything
    | Only of string list

/// The switches this repository reads. The sweep in ApprovalTests holds every site to this list.
[<Literal>]
let Api = "CORE_APPROVE_API"

[<Literal>]
let Wire = "CORE_APPROVE_WIRE"

[<Literal>]
let Ladder = "CORE_APPROVE_LADDER"

[<Literal>]
let Readme = "CORE_APPROVE_README"

[<Literal>]
let Docs = "CORE_APPROVE_DOCS"

[<Literal>]
let Regen = "FUARAN_REGEN"

// ---- the projection registry (Phase 503) -----------------------------------------------------
//
// `projections.json` beside this project lists every committed artefact the repository generates,
// with the verb that writes it, the switch and stem that rewrite it from inside the suite, the family
// that holds it and the copies other repositories carry. The switches' fixed stems are read from it,
// so a new projection is one row; the `Projections` family (ApprovalTests) holds the rest of it.

/// One declared copy of a generated artefact in another repository, written `<repo>:<path>`, both
/// halves relative to the workspace root that holds the two checkouts side by side.
type Copy =
    { Repo: string
      Path: string }

    /// The `<repo>:<path>` spelling.
    member c.Spelling = c.Repo + ":" + c.Path

/// One row of the registry.
type Projection =
    {
        /// Repository-relative, forward-slashed; `{package}` stands for a package id.
        Path: string
        /// The test runner's verb that writes it (`--emit-laws`), if one does.
        Render: string option
        /// The approval switch that rewrites it from inside the suite, if one does.
        Switch: string option
        /// That switch's filter stem; `{package}` where the packable roster decides.
        Stem: string option
        /// The test module (file name without `.fs`) whose family reds when it drifts.
        HeldBy: string
        Copies: Copy list
        /// The version ledger reads it as a derived file stamped with the version.
        VersionStamped: bool
    }

/// The registry, repo-relative.
[<Literal>]
let RegistryPath = "tests/Fuaran.Core.Tests/projections.json"

/// The placeholder a template row carries for a package id.
[<Literal>]
let PackageHole = "{package}"

/// A `<repo>:<path>` copy, or why it is not one.
let parseCopy (s: string) : Result<Copy, string> =
    match s.IndexOf ':' with
    | i when i > 0 && i < s.Length - 1 ->
        let repo, path = s.Substring(0, i), s.Substring(i + 1)

        if
            repo.Contains '\\'
            || path.Contains '\\'
            || path.Contains ':'
            || repo.EndsWith '/'
            || path.StartsWith '/'
        then
            Error(sprintf "`%s` is not `<repo>:<path>` (forward slashes, one colon, no slash at the join)" s)
        else
            Ok { Repo = repo; Path = path }
    | _ -> Error(sprintf "`%s` is not `<repo>:<path>`" s)

let private known =
    set [ "path"; "render"; "switch"; "stem"; "heldBy"; "copies"; "versionStamped" ]

let private str (e: JsonElement) (name: string) =
    match e.TryGetProperty name with
    | true, v when v.ValueKind = JsonValueKind.String -> Some(v.GetString())
    | _ -> None

/// One row, or every reason it is not well formed.
let private parseRow (at: string) (e: JsonElement) : Result<Projection, string list> =
    if e.ValueKind <> JsonValueKind.Object then
        Error [ sprintf "%s is not an object" at ]
    else
        let unknown =
            e.EnumerateObject()
            |> Seq.map _.Name
            |> Seq.filter (known.Contains >> not)
            |> Seq.map (sprintf "%s: unknown member `%s`" at)
            |> Seq.toList

        let copies =
            match e.TryGetProperty "copies" with
            | true, c when c.ValueKind = JsonValueKind.Array ->
                c.EnumerateArray()
                |> Seq.map (fun x ->
                    if x.ValueKind = JsonValueKind.String then
                        parseCopy (x.GetString())
                    else
                        Error "a copy is not a string")
                |> Seq.toList
            | true, _ -> [ Error "`copies` is not an array" ]
            | _ -> []

        let row =
            { Path = str e "path" |> Option.defaultValue ""
              Render = str e "render"
              Switch = str e "switch"
              Stem = str e "stem"
              HeldBy = str e "heldBy" |> Option.defaultValue ""
              Copies = copies |> List.choose Result.toOption
              VersionStamped =
                match e.TryGetProperty "versionStamped" with
                | true, v -> v.ValueKind = JsonValueKind.True
                | _ -> false }

        let faults =
            unknown
            @ (copies
               |> List.choose (function
                   | Error why -> Some(sprintf "%s: %s" at why)
                   | Ok _ -> None))
            @ [ if row.Path = "" then
                    yield sprintf "%s has no `path`" at
                if row.HeldBy = "" then
                    yield sprintf "%s (%s) has no `heldBy`" at row.Path
                if row.Switch.IsSome <> row.Stem.IsSome then
                    yield sprintf "%s (%s) carries a switch without its stem, or a stem without its switch" at row.Path
                if row.Path.Contains PackageHole <> (row.Stem = Some PackageHole) then
                    yield sprintf "%s (%s): a `%s` path and a `%s` stem go together" at row.Path PackageHole PackageHole
                match row.Render with
                | Some r when not (r.StartsWith "--") ->
                    yield sprintf "%s (%s): `render` is not a `--<verb>`" at row.Path
                | _ -> ()
                if row.VersionStamped && row.Copies.IsEmpty then
                    yield sprintf "%s (%s) is version-stamped and declares no copy" at row.Path
                if not row.Copies.IsEmpty && row.Render.IsNone then
                    yield sprintf "%s (%s) declares a copy and no verb to regenerate it with" at row.Path ]

        if faults.IsEmpty then Ok row else Error faults

/// The registry's rows from its text, or every reason it is not well formed: an unknown member, a
/// missing path or holder, a switch without its stem (or the reverse), a template path without a
/// template stem (or the reverse), a verb that is not `--<name>`, a copy not in the one spelling, a
/// version-stamped row with no copy, or two rows with one path and one stem.
let parseRegistry (json: string) : Result<Projection list, string list> =
    try
        use doc = JsonDocument.Parse json

        match doc.RootElement.TryGetProperty "rows" with
        | true, rows when rows.ValueKind = JsonValueKind.Array ->
            let parsed =
                rows.EnumerateArray()
                |> Seq.toList
                |> List.mapi (fun i e -> parseRow (sprintf "row %d" (i + 1)) e)

            let rows = parsed |> List.choose Result.toOption

            let twice =
                rows
                |> List.countBy (fun r -> r.Path, r.Stem)
                |> List.filter (fun (_, n) -> n > 1)
                |> List.map (fun ((p, _), _) -> sprintf "%s is declared twice with one stem" p)

            match
                (parsed
                 |> List.collect (function
                     | Error es -> es
                     | Ok _ -> []))
                @ twice
            with
            | [] -> Ok rows
            | es -> Error es
        | _ -> Error [ "the registry has no `rows` array" ]
    with :? JsonException as ex ->
        Error [ sprintf "the registry is not valid JSON: %s" ex.Message ]

/// The committed registry, read once.
let registry: Lazy<Projection list> =
    lazy
        (match parseRegistry (File.ReadAllText(Repo.file RegistryPath)) with
         | Ok rows -> rows
         | Error es -> failwithf "%s is not well formed:\n  %s" RegistryPath (String.concat "\n  " es))

/// The stems `name` governs when the registry fixes them: `None` for a switch the registry gives no
/// row, or one whose stems are the packable roster (a `{package}` row), known only at run time.
let fixedStemsIn (rows: Projection list) (name: string) : string list option =
    match rows |> List.filter (fun r -> r.Switch = Some name) with
    | [] -> None
    | rs when rs |> List.exists (fun r -> r.Stem = Some PackageHole) -> None
    | rs -> Some(rs |> List.choose _.Stem |> List.distinct)

/// The stems a switch governs when they are fixed, read from the registry. The API and wire switches
/// are not: their stems are the packable roster, so their sites check a filter with `requireMatched`
/// against the roster they iterate.
let fixedStems (name: string) : string list option = fixedStemsIn registry.Value name

// ---- the stems the sites name ---------------------------------------------------------------
//
// Each site that rewrites a fixed-stem projection names its stem through one of these handles, so a
// typo is a compile error rather than a quiet no-op. The handles are names, not the roster: the
// `Projections` family holds every handle to be a registry row and every fixed-stem row to have one.

/// Stems of the generated modules `FUARAN_REGEN` governs (the file name without its extension).
module Regenerated =
    [<Literal>]
    let Derive = "DeriveGenerated"

    [<Literal>]
    let DocAnnotated = "DocAnnotatedGenerated"

    [<Literal>]
    let SpecDecoders = "SpecDecodersGenerated"

    [<Literal>]
    let Mini = "MiniGenerated"

    [<Literal>]
    let Spike = "spike"

    [<Literal>]
    let Doc = "DocGenerated"

    [<Literal>]
    let CapabilitySeam = "CapabilitySeamCodec"

    [<Literal>]
    let PipelineSeam = "PipelineSeamCodec"

    [<Literal>]
    let QuerySeam = "QuerySeamCodec"

    [<Literal>]
