/// Stems of the single files the remaining switches govern.
module Files =
    [<Literal>]
    let Readme = "README"

    [<Literal>]
    let DocCoverage = "doc-coverage"

    /// The generated index block at the head of `DECISIONS.md` (DecisionsTests).
    [<Literal>]
    let Decisions = "DECISIONS"

    /// The release ledger's index, `docs/releases/README.md` (LedgerTests).
    [<Literal>]
    let LedgerIndex = "ledger-index"

