    [<Literal>]
    let Contributing = "CONTRIBUTING"

    /// The JSON Schema of `idl.json` (Phase 527), the artifact codec's schema stamped (IdlArtifactTests).
    [<Literal>]
    let IdlSchema = "idl-schema"

// The pure reading of a switch's value; the one place the truthiness rule lives.
let parse (value: string) : Request =
    match value with
    | null -> NotRequested
    | v ->
        let t = v.Trim()

        if t = "" || t = "0" || t.Equals("false", StringComparison.OrdinalIgnoreCase) then
            NotRequested
        elif t = "1" || t.Equals("true", StringComparison.OrdinalIgnoreCase) then
            Everything
        else
            t.Split([| ',' |], StringSplitOptions.RemoveEmptyEntries ||| StringSplitOptions.TrimEntries)
            |> List.ofArray
            |> function
                | [] -> NotRequested
                | stems -> Only stems

let private read (name: string) : Request =
    parse (Environment.GetEnvironmentVariable name)

/// Is the switch set at all (for every file, or for a filter)?
let requested (name: string) : bool = read name <> NotRequested

/// The switch's filter, when its value is one: the stems as written, comma-joined; else `None`.
let scope (name: string) : string option =
    match read name with
    | Only stems -> Some(String.concat "," stems)
    | NotRequested
    | Everything -> None

let private same (a: string) (b: string) =
    String.Equals(a, b, StringComparison.OrdinalIgnoreCase)

// ---- the pure core: each decision takes the Request it is deciding about, so the tests
// ---- exercise it without ever setting a real switch in the shared process environment.

/// The filter's stems that match none of `stems` (always empty for a bare `1` or an unset switch).
let unmatchedFor (request: Request) (stems: string list) : string list =
    match request with
    | Only wanted -> wanted |> List.filter (fun w -> not (stems |> List.exists (same w)))
    | NotRequested
    | Everything -> []

/// Red, by name, when `request` carries a filter naming something outside `stems`.
let requireMatchedFor (request: Request) (name: string) (stems: string list) : unit =
    match unmatchedFor request stems with
    | [] -> ()
    | bad ->
        failtestf
            "%s=%s names nothing it governs: %s. It governs: %s. A filter that matches nothing is an error, never a no-op."
            name
            (match request with
             | Only s -> String.concat "," s
             | _ -> "")
            (String.concat ", " bad)
            (match stems with
             | [] -> "(no files)"
             | _ -> String.concat ", " stems)

/// May the site holding `stem` rewrite its file under `request`? For a switch whose stems are fixed
/// in source a filter naming no known stem is red here, so a mistyped filter cannot pass quietly.
let admitsFor (request: Request) (name: string) (stem: string) : bool =
    fixedStems name |> Option.iter (requireMatchedFor request name)

    match request with
    | NotRequested -> false
    | Everything -> true
    | Only wanted -> wanted |> List.exists (same stem)

/// Write `text` to `path` when `request` admits the site and the bytes differ, printing the file so
/// the "stage by name" step reads the list. Returns whether the file was rewritten.
let writeFor (request: Request) (name: string) (stem: string) (path: string) (text: string) : bool =
    if not (admitsFor request name stem) then
        false
    else
        let existing = if File.Exists path then File.ReadAllText path else null

        if existing = text then
            false
        else
            File.WriteAllText(path, text)
            printfn "%s: wrote %s" name path
            true

// ---- the environment-reading surface every site uses ---------------------------------------

/// The filter's stems that match none of `stems`, for the switch as the environment sets it.
let unmatched (name: string) (stems: string list) : string list = unmatchedFor (read name) stems

/// Red, by name, when the switch carries a filter naming something outside `stems`.
let requireMatched (name: string) (stems: string list) : unit =
    requireMatchedFor (read name) name stems

/// May the site holding `stem` rewrite its file now?
let admits (name: string) (stem: string) : bool = admitsFor (read name) name stem

/// Write `text` to `path` when the site is admitted and the bytes differ; see `writeFor`.
let write (name: string) (stem: string) (path: string) (text: string) : bool =
    writeFor (read name) name stem path text

/// Red, by name, when the switch carries a filter naming nothing it governs, whether or not the
/// file at the calling site has drifted. A site whose rewrite sits behind a content comparison
/// calls this FIRST, so a mistyped filter is never ignored just because the content is current.
/// A switch governed by the packable roster (API, wire) has no fixed stems and is checked by its
/// own site against the roster it iterates.
let validate (name: string) : unit =
    fixedStems name |> Option.iter (requireMatched name)
